    "explanation": "Medical-Surgical Rationale: In adult clinical practice, \"< 2.2 L/min/m²\" is the established standard for \"Cardiac Output and Index\". Cardiac Index normal is 2.5 - 4.0 L/min/m²; < 2.2 L/min/m² is a threat to tissue oxygenation and indicates beginning treatment.",
    "source_pdf_ref": "MS_W7-10_MIDTERMS.pdf, Page 12",
    "topic": "Cardiac Output and Index",
    "approval_status": "approved"
